-- BUDDY: textos del catálogo legibles para alguien que nunca ha pisado un gimnasio (18/11).
-- Solo cambia textos: name, technique y light_note de cada ejercicio, y el nombre de algunos tipos de equipo.
-- No toca IDs, articulaciones (joints, joints_light), regiones ni cargas.
-- Criterio: castellano de España, tú, frases cortas, sin jerga sin explicar.
--   technique: 2 o 3 frases (colocación, movimiento, clave), como mucho 200 caracteres.
--   light_note: qué vigilar en las zonas de contribución leve y siempre termina con
--               «Si notas dolor, para y márcalo como molestia.» No es consejo médico: no diagnostica ni promete nada.
-- En equipo sin carga externa (suelo, barra de dominadas, paralelas, banco de hiperextensiones), el peso es
-- el que se añade, y la técnica lo dice como «empieza sin peso extra».

update public.exercises as e set
  name = t.name,
  technique = t.technique,
  light_note = t.light_note
from (values
  -- Empuje superior horizontal
  ('press_pecho_maquina', 'Press de pecho en máquina', 'Ajusta el asiento para que las asas queden a la altura del pecho. Empuja hacia delante sin despegar la espalda del respaldo. Vuelve despacio.', 'Las muñecas soportan algo de peso: mantenlas rectas, en línea con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('press_banca_mancuernas', 'Press de banca con mancuernas', 'Túmbate en el banco con los pies en el suelo y los hombros echados hacia atrás. Baja las mancuernas a los lados del pecho, con los codos algo pegados al cuerpo. Empuja sin chocarlas.', null),
  ('press_banca_barra', 'Press de banca con barra', 'Túmbate con los ojos bajo la barra y agárrala algo más ancho que los hombros. Bájala despacio hasta el pecho. Empuja hacia arriba sin rebotar en el pecho.', null),
  ('press_pecho_polea', 'Press de pecho en polea', 'Colócate entre las dos poleas, con un pie adelantado y un asa en cada mano. Empuja hacia delante hasta estirar los brazos. Vuelve despacio, sin llevar los codos por detrás de la espalda.', 'Las muñecas soportan algo de peso: mantenlas rectas, en línea con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('aperturas_contractora', 'Aperturas en contractora', 'Siéntate con la espalda apoyada y los codos un poco doblados. Junta las asas delante del pecho, como si abrazaras un árbol. Abre despacio sin pasar la línea de los hombros.', null),
  ('press_inclinado_mancuernas', 'Press inclinado con mancuernas', 'Inclina el banco un poco, a unos 30 grados, y túmbate con los pies firmes. Baja las mancuernas a los lados de la parte alta del pecho. Empuja hacia arriba sin chocarlas.', null),
  ('press_inclinado_barra', 'Press inclinado con barra', 'Túmbate en el banco inclinado con los pies firmes en el suelo. Baja la barra despacio hasta la parte alta del pecho. Empuja hacia arriba sin rebotar.', null),
  ('press_inclinado_maquina', 'Press inclinado en máquina', 'Ajusta el asiento para que las asas queden a la altura de la parte alta del pecho. Empuja sin despegar la espalda del respaldo. Vuelve despacio.', 'Las muñecas soportan algo de peso: mantenlas rectas, en línea con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('press_banca_multipower', 'Press de banca en multipower', 'Coloca el banco para que la barra guiada baje a la mitad del pecho. Túmbate con los hombros echados hacia atrás y los pies firmes. Baja despacio y empuja sin rebotar.', null),
  ('press_inclinado_multipower', 'Press inclinado en multipower', 'Pon el banco inclinado bajo la barra guiada, que debe bajar a la parte alta del pecho. Baja despacio. Empuja sin llegar a estirar del todo los codos.', null),
  ('aperturas_mancuernas', 'Aperturas con mancuernas', 'Túmbate en el banco con una mancuerna en cada mano y los codos un poco doblados. Abre los brazos en arco hasta notar el pecho estirado, sin bajar de los hombros. Cierra igual.', null),
  ('cruce_poleas', 'Cruce de poleas (aperturas)', 'Colócate entre las dos poleas altas, con un paso adelante y el tronco algo inclinado. Junta las asas delante del pecho en arco, con los codos algo doblados. Vuelve despacio.', null),
  ('fondos_paralelas', 'Fondos en paralelas', 'Sujétate en las paralelas con los brazos estirados. Baja hasta que los codos formen un ángulo recto, sin hundir los hombros, y sube. Empieza sin peso extra.', null),
  ('flexiones', 'Flexiones', 'Manos en el suelo algo más separadas que los hombros y cuerpo recto de la cabeza a los pies. Baja el pecho cerca del suelo y sube sin hundir la cadera. Empieza sin peso extra.', null),
  ('press_suelo_mancuernas', 'Press en el suelo con mancuernas', 'Túmbate boca arriba en el suelo, con las rodillas dobladas y una mancuerna en cada mano. Baja hasta que los brazos rocen el suelo, sin dejarlos caer. Empuja hacia arriba.', null),
  -- Empuje superior vertical
  ('press_hombro_maquina', 'Press de hombro en máquina', 'Siéntate con la espalda pegada al respaldo y las asas a la altura de los hombros. Empuja hacia arriba sin llegar a estirar del todo los codos. Baja despacio.', 'Las muñecas y la zona del cuello trabajan un poco: muñecas rectas, hombros lejos de las orejas y poco peso. Si notas dolor, para y márcalo como molestia.'),
  ('press_militar_mancuernas', 'Press militar con mancuernas', 'Siéntate en un banco con el respaldo vertical y una mancuerna a cada lado de la cabeza. Súbelas sin arquear la espalda. Bájalas despacio hasta la altura de las orejas.', 'El cuello y la parte alta de la espalda trabajan un poco: no subas los hombros hacia las orejas. Si notas dolor, para y márcalo como molestia.'),
  ('press_hombro_multipower', 'Press de hombro en multipower', 'Siéntate en un banco con respaldo bajo la barra guiada. Empuja hacia arriba sin arquear la espalda, con la barra pasando por delante de la cara. Baja despacio hasta la barbilla.', 'El cuello y la parte alta de la espalda trabajan un poco: no subas los hombros hacia las orejas. Si notas dolor, para y márcalo como molestia.'),
  ('elevaciones_laterales_maq', 'Elevaciones laterales en máquina', 'Ajusta el asiento para que tus hombros queden a la altura del punto de giro de la máquina. Sube los brazos hacia los lados hasta los hombros. Baja despacio, sin encogerte.', null),
  ('elevaciones_laterales_manc', 'Elevaciones laterales con mancuernas', 'De pie, con una mancuerna en cada mano y los codos un poco doblados. Sube los brazos hacia los lados hasta la altura de los hombros. Baja más despacio de lo que subes.', null),
  ('press_militar_barra', 'Press militar con barra de pie', 'De pie, con la barra apoyada delante de los hombros. Aprieta glúteos y abdomen y súbela por delante de la cara hasta encima de la cabeza. No arquees la espalda.', 'El cuello y la parte alta de la espalda trabajan un poco: no subas los hombros hacia las orejas. Si notas dolor, para y márcalo como molestia.'),
  ('press_arnold', 'Press Arnold con mancuernas (con giro)', 'Siéntate con la espalda apoyada y las mancuernas delante de la cara, palmas hacia ti. Súbelas girando las palmas hacia delante. Baja deshaciendo el giro, sin arquear la espalda.', null),
  ('elevaciones_laterales_polea', 'Elevación lateral en polea', 'Ponte de lado a la polea baja y agarra el asa con la mano más lejana. Sube el brazo hacia el lado hasta la altura del hombro, con el codo algo doblado. Baja despacio.', null),
  ('elevaciones_frontales_manc', 'Elevaciones frontales con mancuernas', 'De pie, con una mancuerna en cada mano y los codos casi rectos. Sube las pesas por delante hasta la altura de los hombros. Baja despacio, sin balancear el cuerpo.', null),
  ('flexiones_pica', 'Flexiones en pica (cadera alta)', 'Manos y pies en el suelo con la cadera arriba, formando una V al revés. Baja la cabeza hacia el suelo, entre las manos, y empuja para subir. Empieza sin peso extra.', null),
  ('press_hombro_kettlebell', 'Press de hombro con kettlebell', 'La pesa descansa sobre el antebrazo, a la altura del hombro, con la muñeca recta. Empújala hacia arriba hasta estirar el brazo. Baja despacio, sin arquear la espalda.', null),
  -- Tracción superior horizontal
  ('remo_sentado_polea', 'Remo sentado en polea', 'Siéntate con los pies en los apoyos y las rodillas algo dobladas. Tira del agarre hacia el abdomen, juntando los omóplatos. Vuelve estirando los brazos sin balancear el tronco.', null),
  ('remo_maquina', 'Remo en máquina', 'Apoya el pecho en la almohadilla y agarra las asas con los brazos estirados. Tira llevando los codos hacia atrás y junta los omóplatos. Vuelve despacio.', null),
  ('remo_mancuerna', 'Remo con mancuerna', 'Apoya una mano y una rodilla en el banco, con la espalda recta. Sube la mancuerna hacia la cadera con el otro brazo. No gires el tronco al tirar.', null),
  ('pajaro_contractora', 'Pájaros en contractora (aperturas inversas)', 'Siéntate mirando al respaldo, con el pecho apoyado y los brazos casi rectos. Abre los brazos hacia atrás hasta la línea de los hombros. Vuelve despacio.', null),
  ('remo_barra', 'Remo con barra', 'Inclina el tronco hacia delante, a unos 45 grados, con la espalda recta y las rodillas algo dobladas. Lleva la barra hacia el abdomen juntando los omóplatos. Baja sin tirones.', null),
  ('remo_pecho_apoyado_manc', 'Remo con mancuernas en banco inclinado', 'Túmbate boca abajo en un banco inclinado, con una mancuerna en cada mano. Sube las pesas hacia la cadera juntando los omóplatos. Baja hasta estirar los brazos.', null),
  ('remo_polea_unilateral', 'Remo a una mano en polea', 'Polea a media altura y el asa en una mano, con el tronco firme. Tira del asa hacia la cadera sin girar el cuerpo. Vuelve despacio hasta estirar el brazo.', null),
  ('remo_multipower', 'Remo en multipower', 'Inclina el tronco hacia delante con la espalda recta y las rodillas algo dobladas. Lleva la barra guiada hacia el abdomen. Bájala sin redondear la espalda.', null),
  ('face_pull', 'Face pull en polea (tirón a la cara)', 'Pon la cuerda en la polea a la altura de la cara. Tira hacia la frente separando las manos, con los codos altos. Vuelve despacio.', null),
  ('pajaro_mancuernas_inclinado', 'Pájaros en banco inclinado (aperturas inversas)', 'Túmbate boca abajo en un banco inclinado, con una mancuerna en cada mano y los brazos casi rectos. Ábrelos hacia los lados hasta la línea de los hombros. Baja despacio.', null),
  ('remo_polea_agarre_ancho', 'Remo en polea con agarre ancho', 'Siéntate en la polea de remo con una barra larga, agarrada por fuera de los hombros. Tira hacia la parte baja del pecho con los codos abiertos. Vuelve sin balancear el tronco.', null),
  ('remo_maquina_unilateral', 'Remo en máquina a un brazo', 'Apoya el pecho en la almohadilla y trabaja un brazo cada vez. Lleva el codo hacia atrás sin girar el tronco. Vuelve hasta estirar el brazo del todo.', null),
  -- Tracción superior vertical
  ('jalon_pecho', 'Jalón al pecho', 'Siéntate con los muslos sujetos bajo el rodillo y agarra la barra algo más ancho que los hombros. Bájala hasta la parte alta del pecho. Sube despacio hasta estirar los brazos.', null),
  ('jalon_agarre_estrecho', 'Jalón con agarre estrecho', 'Usa el agarre de asas juntas e inclina el tronco un poco hacia atrás. Lleva el agarre al pecho con los codos pegados al cuerpo. Sube despacio.', null),
  ('jalon_polea_doble', 'Jalón con polea doble', 'De rodillas o sentado entre las dos poleas altas, con un asa en cada mano. Tira hacia los hombros llevando los codos hacia abajo. Sube despacio hasta estirar los brazos.', null),
  ('pullover_polea', 'Pullover en polea (brazos rectos)', 'De pie frente a la polea alta, con la barra o la cuerda y los brazos casi rectos. Baja el agarre en arco hasta los muslos. Vuelve despacio sin pasar de la altura de la cabeza.', null),
  ('dominadas', 'Dominadas', 'Cuélgate de la barra con las palmas hacia delante, algo más separadas que los hombros. Sube hasta pasar la barbilla de la barra, sin balanceo, y baja del todo. Empieza sin peso extra.', null),
  ('dominadas_supinas', 'Dominadas con palmas hacia ti (supinas)', 'Cuélgate de la barra con las palmas hacia ti, a la anchura de los hombros. Sube sacando pecho y baja despacio hasta estirar los brazos. Empieza sin peso extra.', null),
  ('jalon_supino', 'Jalón con palmas hacia ti (supino)', 'Agarra la barra con las palmas hacia ti, a la anchura de los hombros. Bájala al pecho con los codos pegados al cuerpo. Sube despacio.', null),
  ('jalon_unilateral_polea', 'Jalón a una mano en polea', 'De rodillas o sentado junto a la polea alta, con el asa en una mano. Baja el asa hacia el hombro llevando el codo a la cadera. Sube despacio hasta estirar el brazo.', null),
  ('pullover_mancuerna', 'Pullover con mancuerna', 'Apoya la parte alta de la espalda en el banco y sujeta una mancuerna con las dos manos sobre el pecho. Llévala atrás con los brazos casi rectos, hasta donde estés cómodo. Vuelve.', null),
  -- Empuje inferior
  ('prensa_piernas', 'Prensa de piernas', 'Espalda apoyada y pies en el centro de la plataforma, separados como tu cadera. Baja solo hasta donde la zona lumbar siga pegada al respaldo. Empuja sin estirar del todo las rodillas.', 'La zona lumbar (parte baja de la espalda) trabaja un poco: que no se despegue del respaldo. Si notas dolor, para y márcalo como molestia.'),
  ('sentadilla_hack', 'Sentadilla hack (máquina)', 'Espalda pegada al respaldo, hombros bajo las almohadillas y pies algo adelantados. Baja despacio doblando las rodillas. Sube empujando con todo el pie, sin estirarlas del todo.', 'Tus hombros solo aguantan las almohadillas de la máquina: que apoyen cómodas, sin presión. Si notas dolor, para y márcalo como molestia.'),
  ('sentadilla_multipower', 'Sentadilla en multipower', 'Barra guiada sobre la parte alta de la espalda y pies un poco por delante del cuerpo. Baja con el pecho alto hasta donde estés cómodo. Sube sin estirar del todo las rodillas.', null),
  ('sentadilla_goblet', 'Sentadilla goblet con kettlebell', 'Sujeta la pesa pegada al pecho, con los codos hacia abajo. Baja entre las piernas con el pecho alto. Sube empujando con todo el pie.', 'La zona lumbar, los codos y las muñecas trabajan un poco: usa poco peso y baja hasta donde estés cómodo. Si notas dolor, para y márcalo como molestia.'),
  ('extension_cuadriceps', 'Extensión de cuádriceps', 'Ajusta el respaldo para que la rodilla quede a la altura del punto de giro de la máquina. Estira las piernas sin dar tirones. Baja despacio.', null),
  ('zancada_mancuernas', 'Zancada con mancuernas', 'De pie, con una mancuerna en cada mano, da un paso largo hacia delante. Baja hasta que la rodilla de atrás casi toque el suelo. Vuelve empujando con el talón de delante.', 'La zona lumbar y las muñecas trabajan un poco: tronco recto, muñecas firmes y poco peso. Si notas dolor, para y márcalo como molestia.'),
  ('gemelo_maquina', 'Gemelo de pie en máquina', 'Hombros bajo las almohadillas y la punta de los pies en el borde del escalón. Sube los talones todo lo que puedas y aguanta un segundo. Baja hasta notar la pantorrilla estirada.', 'Tus hombros solo aguantan las almohadillas de la máquina: que apoyen cómodas, sin presión. Si notas dolor, para y márcalo como molestia.'),
  ('sentadilla_barra', 'Sentadilla con barra', 'En el rack, con las barras de seguridad puestas, apoya la barra en la parte alta de la espalda. Baja con el pecho alto y las rodillas hacia donde apuntan los pies. Sube con todo el pie.', null),
  ('sentadilla_goblet_manc', 'Sentadilla goblet con mancuerna', 'Sujeta una mancuerna en vertical, pegada al pecho. Baja entre las piernas con el pecho alto. Sube empujando con todo el pie.', 'La zona lumbar, los codos y las muñecas trabajan un poco: usa poco peso y baja hasta donde estés cómodo. Si notas dolor, para y márcalo como molestia.'),
  ('sentadilla_cajon_alto', 'Sentadilla a banco alto con mancuerna', 'De pie delante de un banco alto, con la mancuerna pegada al pecho. Echa la cadera atrás hasta rozar el banco, sin dejarte caer. Sube empujando con todo el pie.', 'La rodilla y la zona lumbar trabajan un poco: baja despacio, sin rebotar, y solo hasta donde estés cómodo. Si notas dolor, para y márcalo como molestia.'),
  ('zancada_atras_manc', 'Zancada hacia atrás con mancuernas', 'De pie, con una mancuerna en cada mano, da un paso hacia atrás. Baja hasta que la rodilla de atrás casi toque el suelo. Vuelve empujando con el pie de delante.', 'Las muñecas soportan algo de peso: mantenlas rectas, en línea con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('sentadilla_bulgara', 'Sentadilla búlgara con mancuernas', 'Apoya el empeine del pie de atrás en un banco y adelanta bien el otro pie. Baja recto, con el tronco firme. Sube empujando con el talón de delante.', 'Las muñecas soportan algo de peso: mantenlas rectas, en línea con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('subida_banco', 'Subida al banco con mancuernas', 'Con una mancuerna en cada mano, apoya todo un pie en el banco. Sube empujando con esa pierna, sin impulsarte con la de abajo. Baja despacio.', 'Las muñecas soportan algo de peso: mantenlas rectas, en línea con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('prensa_unilateral', 'Prensa a una pierna', 'Pon un solo pie en el centro de la plataforma. Baja solo hasta donde la zona lumbar siga pegada al respaldo. Empuja sin estirar del todo la rodilla.', 'La zona lumbar (parte baja de la espalda) trabaja un poco: que no se despegue del respaldo. Si notas dolor, para y márcalo como molestia.'),
  ('extension_cuadriceps_unilateral', 'Extensión de cuádriceps a una pierna', 'Ajusta el respaldo para que la rodilla quede a la altura del punto de giro de la máquina. Sube con una sola pierna, sin tirones, y aguanta un segundo arriba. Baja despacio.', null),
  ('zancada_multipower', 'Zancada en multipower', 'Barra guiada sobre la parte alta de la espalda y un pie adelantado. Baja en vertical hasta que la rodilla de atrás casi toque el suelo. Sube empujando con el pie de delante.', null),
  ('gemelo_prensa', 'Gemelo en prensa', 'Pon solo la punta de los pies en el borde bajo de la plataforma, con las rodillas casi rectas. Empuja con las puntas. Baja hasta notar la pantorrilla estirada.', 'La rodilla apenas se mueve: mantenla casi recta, sin llegar a estirarla del todo. Si notas dolor, para y márcalo como molestia.'),
  ('gemelo_sentado_maquina', 'Gemelo sentado en máquina', 'Siéntate con la almohadilla sobre los muslos, cerca de las rodillas, y las puntas en el escalón. Sube los talones todo lo que puedas. Baja despacio hasta notar el estiramiento.', 'La rodilla apenas se mueve: solo sujeta la almohadilla. Si notas dolor, para y márcalo como molestia.'),
  ('gemelo_multipower', 'Gemelo de pie en multipower', 'Barra guiada sobre la parte alta de la espalda y la punta de los pies en un disco o escalón. Sube los talones todo lo que puedas. Baja sin rebotar.', null),
  ('gemelo_mancuerna', 'Gemelo a una pierna con mancuerna', 'Punta de un pie en un escalón, la mancuerna en una mano y la otra mano en la pared. Sube el talón todo lo que puedas. Baja despacio.', null),
  -- Tracción inferior
  ('curl_femoral_tumbado', 'Curl femoral tumbado', 'Túmbate boca abajo con las rodillas justo fuera del banco y el rodillo sobre los tobillos. Lleva los talones hacia los glúteos. Baja despacio, sin despegar la cadera.', null),
  ('curl_femoral_sentado', 'Curl femoral sentado', 'Ajusta la máquina para que la rodilla quede a la altura del punto de giro y los muslos bien sujetos. Dobla las rodillas llevando el rodillo hacia abajo. Vuelve despacio.', null),
  ('peso_muerto_rumano_manc', 'Peso muerto rumano con mancuernas', 'De pie, con las rodillas un poco dobladas y una mancuerna en cada mano. Echa la cadera atrás y baja las pesas pegadas a las piernas, con la espalda recta. Sube apretando los glúteos.', 'Las muñecas y la zona del cuello trabajan un poco: muñecas rectas, cuello en línea con la espalda y poco peso. Si notas dolor, para y márcalo como molestia.'),
  ('peso_muerto_rumano_barra', 'Peso muerto rumano con barra', 'De pie, con la barra en las manos pegada a los muslos. Echa la cadera atrás con la espalda recta hasta notar tirantez detrás del muslo. Sube apretando los glúteos.', 'Las muñecas y la zona del cuello trabajan un poco: muñecas rectas, cuello en línea con la espalda y poco peso. Si notas dolor, para y márcalo como molestia.'),
  ('hip_thrust_maquina', 'Hip thrust en máquina (empuje de cadera)', 'Apoya la parte alta de la espalda y pon los pies separados como tu cadera. Sube la cadera apretando los glúteos hasta que tronco y muslos queden en línea. No arquees la espalda.', 'La zona lumbar (parte baja de la espalda) trabaja un poco: arriba, detente cuando tronco y muslos estén en línea. Si notas dolor, para y márcalo como molestia.'),
  ('hip_thrust_barra', 'Hip thrust con barra (empuje de cadera)', 'Apoya la parte alta de la espalda en un banco y la barra, con una funda acolchada, sobre la cadera. Sube hasta que tronco y muslos queden en línea. Mete la barbilla y no arquees.', 'La zona lumbar (parte baja de la espalda) trabaja un poco: arriba, detente cuando tronco y muslos estén en línea. Si notas dolor, para y márcalo como molestia.'),
  ('abductores_maquina', 'Abductores en máquina (abrir piernas)', 'Siéntate con la espalda apoyada y las almohadillas por fuera de las rodillas. Abre las piernas sin dar tirones. Vuelve despacio, sin que el peso choque.', null),
  ('peso_muerto_barra', 'Peso muerto con barra', 'Barra en el suelo sobre la mitad del pie y espalda recta al agarrarla. Sube empujando el suelo con las piernas, con la barra pegada al cuerpo. Baja con el mismo control.', 'Las muñecas y la zona del cuello trabajan un poco: muñecas rectas, cuello en línea con la espalda y poco peso. Si notas dolor, para y márcalo como molestia.'),
  ('peso_muerto_rumano_multipower', 'Peso muerto rumano en multipower', 'De pie, con las rodillas un poco dobladas y la barra guiada en las manos. Echa la cadera atrás, con la barra pegada a las piernas y la espalda recta. Sube apretando los glúteos.', 'Las muñecas soportan algo de peso: mantenlas rectas, en línea con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('hiperextensiones', 'Hiperextensiones', 'Coloca la almohadilla justo bajo la cadera y cruza los brazos. Baja con la espalda recta y sube hasta que el cuerpo quede en línea, sin arquearte. Empieza sin peso extra.', null),
  ('puente_gluteo_mancuerna', 'Puente de glúteo con mancuerna', 'Túmbate boca arriba con las rodillas dobladas y la mancuerna sobre la cadera. Sube la cadera apretando los glúteos hasta alinear muslos y tronco. No arquees la espalda arriba.', 'La zona lumbar (parte baja de la espalda) trabaja un poco: arriba, detente cuando tronco y muslos estén en línea. Si notas dolor, para y márcalo como molestia.'),
  ('hip_thrust_multipower', 'Hip thrust en multipower (empuje de cadera)', 'Apoya la parte alta de la espalda en un banco y la barra guiada, con funda acolchada, sobre la cadera. Sube hasta alinear tronco y muslos. Baja despacio.', 'La zona lumbar (parte baja de la espalda) trabaja un poco: arriba, detente cuando tronco y muslos estén en línea. Si notas dolor, para y márcalo como molestia.'),
  ('patada_gluteo_polea', 'Patada de glúteo en polea', 'Engancha la tobillera (una correa al tobillo) a la polea baja y apoya las manos. Lleva la pierna hacia atrás apretando el glúteo. No arquees la zona lumbar.', null),
  ('abductores_polea', 'Abducción de cadera en polea (abrir pierna)', 'Ponte de lado a la polea baja, con la tobillera en la pierna más lejana. Separa esa pierna hacia fuera sin inclinar el tronco. Vuelve despacio.', null),
  ('aductores_maquina', 'Aductores en máquina (cerrar piernas)', 'Siéntate con las almohadillas por dentro de las rodillas y ábrelas solo hasta un estiramiento cómodo. Junta las piernas sin dar tirones. Vuelve despacio.', null),
  ('peso_muerto_rumano_unilateral', 'Peso muerto rumano a una pierna', 'De pie sobre una pierna, con la rodilla un poco doblada y una mancuerna en la mano. Inclina el tronco mientras la otra pierna va atrás, con la espalda recta. Vuelve despacio.', null),
  ('hip_thrust_mancuerna', 'Hip thrust con mancuerna (empuje de cadera)', 'Apoya la parte alta de la espalda en un banco y la mancuerna sobre la cadera. Sube hasta que tronco y muslos queden en línea, con la barbilla recogida. Baja despacio.', 'La zona lumbar (parte baja de la espalda) trabaja un poco: arriba, detente cuando tronco y muslos estén en línea. Si notas dolor, para y márcalo como molestia.'),
  ('peso_muerto_rumano_kb', 'Peso muerto rumano con kettlebell', 'Sujeta la pesa con las dos manos delante de los muslos. Echa la cadera atrás con la espalda recta hasta notar tirantez detrás del muslo. Sube apretando los glúteos.', 'Las muñecas soportan algo de peso: mantenlas rectas, en línea con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('patada_gluteo_maquina', 'Patada de glúteo en máquina', 'Apoya bien el tronco y los brazos en la máquina. Empuja hacia atrás con el talón, apretando el glúteo. No arquees la zona lumbar.', null),
  -- Brazo
  ('curl_biceps_maquina', 'Curl de bíceps en máquina', 'Apoya los brazos en la almohadilla, con los codos a la altura del punto de giro. Sube sin despegar los brazos. Baja despacio, sin estirar del todo de golpe.', 'Tu hombro participa poco aquí: mantén el brazo apoyado y muévete hasta donde estés cómodo. Si notas dolor, para y márcalo como molestia.'),
  ('curl_scott', 'Curl en banco Scott (predicador)', 'Con barra Z o una mancuerna, apoya la parte de atrás del brazo en la almohadilla inclinada. Sube sin despegar el brazo. Baja despacio, sin estirar del todo de golpe.', 'Tu hombro participa poco aquí: mantén el brazo apoyado y muévete hasta donde estés cómodo. Si notas dolor, para y márcalo como molestia.'),
  ('curl_biceps_mancuernas', 'Curl de bíceps con mancuernas', 'De pie, con una mancuerna en cada mano y los codos pegados al cuerpo. Sube girando las palmas hacia arriba. Baja despacio, sin balancearte.', null),
  ('curl_martillo', 'Curl martillo con mancuernas', 'Sujeta las mancuernas con las palmas mirándose, como si llevaras un martillo, y los codos pegados. Sube sin mover los hombros. Baja despacio.', null),
  ('curl_inclinado_mancuernas', 'Curl en banco inclinado con mancuernas', 'Siéntate con la espalda apoyada en un banco inclinado y los brazos colgando. Sube las mancuernas sin adelantar los codos. Baja del todo, despacio.', null),
  ('curl_biceps_polea', 'Curl de bíceps en polea', 'De pie frente a la polea baja, con los codos pegados y el tronco quieto. Sube la barra o las asas doblando los codos. Baja despacio, sin dejar que la polea tire de ti.', null),
  ('curl_barra', 'Curl de bíceps con barra', 'Agarra la barra con las palmas hacia delante, a la anchura de los hombros. Sube con los codos pegados al cuerpo, sin balancear la espalda. Baja despacio.', null),
  ('curl_barra_z', 'Curl de bíceps con barra Z', 'Agarra la barra Z por los tramos inclinados, más cómodos para las muñecas. Sube con los codos pegados, sin balancearte. Baja despacio.', null),
  ('curl_concentrado', 'Curl concentrado con mancuerna', 'Siéntate y apoya el codo en la parte interna del muslo. Sube la mancuerna hacia el hombro. Baja despacio hasta estirar el brazo.', null),
  ('curl_inverso_barra_z', 'Curl inverso con barra Z (palmas hacia abajo)', 'Agarra la barra con las palmas hacia abajo y las muñecas rectas. Sube con los codos pegados al cuerpo. Baja despacio.', null),
  ('curl_muneca', 'Curl de muñeca con mancuerna', 'Apoya el antebrazo en el muslo o en el banco, con la mano por fuera y la palma hacia arriba. Sube la mancuerna moviendo solo la muñeca. Hazlo en un recorrido cómodo.', 'El codo trabaja poco aquí: mantén el antebrazo apoyado y sube despacio. Si notas dolor, para y márcalo como molestia.'),
  ('extension_triceps_maquina', 'Extensión de tríceps en máquina', 'Apoya los brazos en la almohadilla, con los codos a la altura del punto de giro. Estira los brazos sin dar un golpe al final. Vuelve despacio.', 'Tu hombro participa poco aquí: mantén el brazo apoyado y muévete hasta donde estés cómodo. Si notas dolor, para y márcalo como molestia.'),
  ('extension_triceps_polea', 'Extensión de tríceps en polea', 'De pie frente a la polea alta, con los codos pegados al cuerpo. Estira los brazos hacia abajo sin que los codos se adelanten. Sube despacio.', null),
  ('extension_triceps_cuerda', 'Extensión de tríceps con cuerda', 'Cuerda en la polea alta y codos fijos a los lados del cuerpo. Estira los brazos hacia abajo y separa los extremos de la cuerda al final. Sube despacio.', null),
  ('extension_triceps_cabeza_polea', 'Extensión de tríceps sobre la cabeza en polea', 'De espaldas a la polea, con la cuerda detrás de la cabeza y los codos junto a ella. Estira los brazos hacia delante y arriba. No abras los codos.', null),
  ('press_frances_barra_z', 'Press francés con barra Z (tumbado)', 'Túmbate en el banco con la barra Z sobre el pecho y los brazos estirados hacia el techo. Baja la barra hacia la frente doblando solo los codos. Estira sin abrirlos.', null),
  ('extension_triceps_mancuerna_cabeza', 'Extensión de tríceps con mancuerna sobre la cabeza', 'Siéntate con la espalda apoyada y sujeta una mancuerna con las dos manos sobre la cabeza. Bájala por detrás de la cabeza doblando los codos. Estira sin abrir los codos.', null),
  ('patada_triceps_mancuerna', 'Patada de tríceps con mancuerna', 'Apoya una mano y una rodilla en el banco y pega el otro codo al cuerpo. Estira el brazo hacia atrás. Vuelve sin mover el codo.', null),
  ('press_banca_cerrado', 'Press de banca con agarre cerrado', 'Túmbate en el banco y agarra la barra con las manos a la anchura de los hombros. Bájala a la parte baja del pecho con los codos pegados al cuerpo. Empuja hacia arriba.', null),
  ('fondos_maquina', 'Fondos en máquina', 'Siéntate con la espalda apoyada y agarra las asas con los codos hacia atrás. Empuja hacia abajo hasta estirar los brazos. Sube despacio, sin que los hombros se vayan hacia delante.', 'Las muñecas soportan algo de peso: mantenlas rectas, en línea con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  -- Abdomen y tronco
  ('crunch_maquina', 'Crunch abdominal en máquina', 'Siéntate con el pecho contra la almohadilla o las manos en las asas. Encoge el tronco llevando las costillas hacia la cadera. Vuelve despacio.', 'El cuello y los hombros trabajan un poco: no tires con los brazos y usa poco peso. Si notas dolor, para y márcalo como molestia.'),
  ('crunch_polea', 'Crunch abdominal en polea', 'De rodillas frente a la polea alta, con la cuerda junto a la cabeza. Encoge el tronco hacia el suelo, como si te enrollaras. No tires con los brazos.', 'Tu hombro participa poco aquí: solo sujeta la cuerda junto a la cabeza, sin tirar con los brazos. Si notas dolor, para y márcalo como molestia.'),
  ('pallof_polea', 'Press Pallof en polea (aguantar sin girar)', 'De lado a la polea, con el asa agarrada con las dos manos junto al pecho. Estira los brazos delante del pecho sin dejar que el tronco gire. Vuelve despacio.', null),
  ('lenador_polea', 'Leñador en polea (giro de tronco)', 'De lado a la polea, con el asa en las dos manos y los brazos estirados. Lleva el asa en diagonal, girando desde la cadera. Mantén los pies firmes en el suelo.', null),
  ('elevacion_rodillas_paralelas', 'Elevación de rodillas en paralelas', 'Apóyate en las paralelas con los brazos y baja los hombros, lejos de las orejas. Sube las rodillas hacia el pecho sin balancearte. Empieza sin peso extra.', 'El codo trabaja poco aquí: apóyate firme y muévete despacio. Si notas dolor, para y márcalo como molestia.'),
  ('elevacion_rodillas_colgado', 'Elevación de rodillas colgado', 'Cuélgate de la barra con los brazos estirados y sin balancearte. Sube las rodillas hacia el pecho enrollando la cadera y baja despacio. Empieza sin peso extra.', null),
  ('dead_bug', 'Bicho muerto (dead bug)', 'Boca arriba, con los brazos hacia el techo y las rodillas dobladas en ángulo recto. Estira un brazo y la pierna contraria sin despegar la zona lumbar del suelo. Cambia de lado.', 'La zona lumbar y la cadera trabajan un poco: mantén la zona lumbar pegada al suelo y muévete despacio. Si notas dolor, para y márcalo como molestia.'),
  ('bird_dog', 'Cuadrupedia con brazo y pierna (bird dog)', 'A cuatro patas, con la espalda recta. Estira un brazo y la pierna contraria sin girar la cadera, y aguanta un segundo. Vuelve y cambia de lado.', 'La zona lumbar, la cadera y las rodillas trabajan un poco: muévete despacio y apoya las rodillas en la esterilla. Si notas dolor, para y márcalo como molestia.'),
  ('crunch_suelo', 'Crunch abdominal en el suelo', 'Boca arriba, con las rodillas dobladas y los pies en el suelo. Despega solo los hombros, sin tirar del cuello, y baja despacio. Empieza sin peso extra.', null),
  ('elevacion_piernas_suelo', 'Elevación de piernas tumbado', 'Boca arriba, con las manos bajo la cadera. Sube las piernas hasta que apunten al techo. Bájalas despacio sin que la zona lumbar se despegue del suelo.', null),
  ('flexion_lateral_mancuerna', 'Inclinación lateral con mancuerna', 'De pie, con una mancuerna en una mano junto al muslo. Inclínate hacia ese lado sin girar el tronco. Vuelve a ponerte recto.', 'Tu hombro participa poco aquí: solo sujeta la mancuerna, con el brazo relajado. Si notas dolor, para y márcalo como molestia.')
) as t(id, name, technique, light_note)
where e.id = t.id;

-- Tipos de equipo: se aclara entre paréntesis el que puede no reconocerse por el nombre.
update public.equipment_types as q set name = n.name
from (values
  ('sentadilla_hack', 'Sentadilla hack (máquina)'),
  ('maquina_abductores', 'Máquina de abductores (abrir piernas)'),
  ('maquina_aductores', 'Máquina de aductores (cerrar piernas)'),
  ('maquina_hip_thrust', 'Máquina de hip thrust (empuje de cadera)'),
  ('multipower', 'Multipower (barra guiada)'),
  ('jalon', 'Jalón al pecho (polea alta)'),
  ('polea_doble', 'Polea doble (cruce de poleas)'),
  ('contractora', 'Contractora (aperturas de pecho)'),
  ('barra', 'Barra olímpica (barra larga con discos)'),
  ('rack', 'Rack (jaula para sentadilla)'),
  ('kettlebells', 'Kettlebells (pesas rusas)'),
  ('remo_ergometro', 'Remo ergómetro (máquina de remo de cardio)'),
  ('barra_z', 'Barra Z (barra corta en zigzag)'),
  ('banco_hiperextensiones', 'Banco de hiperextensiones (banco de lumbares)'),
  ('esterilla', 'Esterilla (ejercicios en el suelo)')
) as n(id, name)
where q.id = n.id;
